from itertools import product

def solve(coins, weighings_left):
    # coins: list of candidate indices (heavy coin among these)
    if len(coins) == 1:
        return coins[0]
    if weighings_left == 0:
        return None
    # try all splits into left/right groups (equal size), rest off scale
    n = len(coins)
    for k in range(1, n//2 + 1):
        left = coins[:k]
        right = coins[k:2*k]
        rest = coins[2*k:]
        # outcomes: left heavy, right heavy, balance
        branches = [left, right, rest]
        ok = True
        for b in branches:
            if b and solve(b, weighings_left-1) is None:
                ok = False
        if ok:
            return True
    return None

print("12 coins, 3 weighings solvable:", solve(list(range(12)), 3) is not None)
print("13 coins, 3 weighings solvable:", solve(list(range(13)), 3) is not None)
